function DataSilosGetRelatedRecords(record)
{
	var IsValidRecord = x_snc_devtools.IsValidRecord;
	var RenderValue = x_snc_devtools.RenderValue;

	var aRelatedRecords = [];

	var strTable = x_snc_datasilos.GetSupportedTableFromRecord(record);

	if (strTable == 'cmdb_ci')
	{
		// Add your code here...
		var grRecord = new GlideRecord('task'); // TODO: replace with related table
		if (grRecord.get(record.getValue('some_reference_field')) == true) // TODO: replace with field referencing to related record
		{
			aRelatedRecords.push(grRecord);
		}

		return aRelatedRecords;
	}

	return false;
}
